"""Branch models and their small, dependency-free TOML reader."""
import json
import os
import re
from pathlib import Path

BASE_PAT = r'^(master|main|trunk)$'
TAG_PAT = r'^tags/.*$'
DEFAULTS = {
    'git-flow': dict(
        persistence=[BASE_PAT, r'^(develop|dev)$', r'^feature.*$', r'^release.*$', r'^hotfix.*$', r'^bugfix.*$'],
        order=[BASE_PAT, r'^(hotfix|release).*$', r'^(develop|dev)$'],
        terminal_colors=dict(matches=[
            [BASE_PAT, ['bright_blue']], [r'^(develop|dev)$', ['bright_yellow']],
            [r'^(feature|fork/).*$', ['bright_magenta', 'bright_cyan']],
            [r'^release.*$', ['bright_green']], [r'^(bugfix|hotfix).*$', ['bright_red']],
            [TAG_PAT, ['bright_green']]], unknown=['white']),
        svg_colors=dict(matches=[
            [BASE_PAT, ['blue']], [r'^(develop|dev)$', ['orange']],
            [r'^(feature|fork/).*$', ['purple', 'turquoise']], [r'^release.*$', ['green']],
            [r'^(bugfix|hotfix).*$', ['red']], [TAG_PAT, ['green']]], unknown=['gray'])),
    'simple': dict(persistence=[BASE_PAT], order=[TAG_PAT, BASE_PAT],
        terminal_colors=dict(matches=[[BASE_PAT, ['bright_blue']], [TAG_PAT, ['bright_green']]],
                             unknown=['bright_yellow', 'bright_green', 'bright_red', 'bright_magenta', 'bright_cyan']),
        svg_colors=dict(matches=[[BASE_PAT, ['blue']], [TAG_PAT, ['green']]],
                        unknown=['orange', 'green', 'red', 'purple', 'turquoise'])),
    'none': dict(persistence=[], order=[],
        terminal_colors=dict(matches=[], unknown=['bright_blue', 'bright_yellow', 'bright_green', 'bright_red', 'bright_magenta', 'bright_cyan']),
        svg_colors=dict(matches=[], unknown=['blue', 'orange', 'green', 'red', 'purple', 'turquoise']))
}

class ModelError(Exception):
    pass

class TomlError(Exception):
    def __init__(self, message, pos=0):
        self.pos = pos
        super().__init__(message)


def read_toml(text):
    """Read the tables, arrays, scalars and quoted strings used by model files."""
    pos = 0
    root = {}
    table = root
    n = len(text)
    def space():
        nonlocal pos
        while pos < n:
            if text[pos].isspace():
                pos += 1
            elif text[pos] == '#':
                end = text.find('\n', pos)
                pos = n if end < 0 else end + 1
            else:
                break
    def string():
        nonlocal pos
        quote = text[pos]
        start = pos
        pos += 1
        result = ''
        while pos < n:
            c = text[pos]
            pos += 1
            if c == quote:
                return result
            if c == '\\' and quote == '"':
                if pos == n:
                    break
                c = text[pos]
                pos += 1
                if c in {'u','U'}:
                    width = 4 if c == 'u' else 8
                    try:
                        result += chr(int(text[pos:pos+width],16))
                    except ValueError:
                        raise TomlError('invalid unicode escape',pos)
                    pos += width
                    continue
                if c not in 'btnfr"\\':
                    raise TomlError('invalid escape sequence',pos-1)
                c = {'b':'\b','t':'\t','n':'\n','f':'\f','r':'\r','"':'"','\\':'\\'}[c]
            result += c
        raise TomlError('unterminated string', start)
    def value():
        nonlocal pos
        space()
        if pos >= n:
            raise TomlError('expected a value', pos)
        c = text[pos]
        if c in "\"'":
            return string()
        if c == '[':
            pos += 1
            out=[]
            space()
            while pos < n and text[pos] != ']':
                out.append(value())
                space()
                if pos < n and text[pos] == ',':
                    pos += 1
                    space()
                elif pos < n and text[pos] != ']':
                    raise TomlError('expected a comma',pos)
            if pos >= n:
                raise TomlError('unterminated array',pos)
            pos += 1
            return out
        m = re.match(r'[^\s,#\]}]+', text[pos:])
        if not m:
            raise TomlError('expected a value',pos)
        token=m.group()
        pos += len(token)
        if token == 'true': return True
        if token == 'false': return False
        try:
            return int(token.replace('_',''),0) if token.startswith(('0x','0o','0b')) else int(token.replace('_',''))
        except ValueError:
            try: return float(token.replace('_',''))
            except ValueError: raise TomlError('invalid number',pos-len(token))
    while True:
        space()
        if pos >= n: break
        if text[pos] == '[':
            pos += 1
            end=text.find(']',pos)
            if end < 0: raise TomlError('unterminated table',pos)
            name=text[pos:end].strip()
            pos=end+1
            table=root
            for part in name.split('.'):
                table=table.setdefault(part.strip().strip('"\''),{})
            continue
        if text[pos] in "\"'": key=string()
        else:
            m=re.match(r'[A-Za-z0-9_-]+',text[pos:])
            if not m: raise TomlError('expected a key',pos)
            key=m.group();pos+=len(key)
        space()
        if pos >= n or text[pos] != '=': raise TomlError('expected an equals',pos)
        pos += 1
        if key in table: raise TomlError('duplicate key',pos)
        table[key]=value()
    return root


def array_text(values):
    if not values: return '[]'
    if len(values)==1 and isinstance(values[0],str): return '['+json.dumps(values[0])+']'
    return '[\n'+''.join('    '+(json.dumps(v) if isinstance(v,str) else array_text(v))+',\n' for v in values)+']'


def model_text(model):
    out='persistence = '+array_text(model['persistence'])+'\n'
    out+='order = '+array_text(model['order'])+'\n'
    for k in ('terminal_colors','svg_colors'):
        out+='\n['+k+']\n'
        out+='matches = '+array_text(model[k]['matches'])+'\n'
        out+='unknown = '+array_text(model[k]['unknown'])+'\n'
    return out


def config_dir():
    p=os.environ.get('XDG_CONFIG_HOME')
    if not p: p=os.path.join(os.path.expanduser('~'),'.config')
    return Path(p)/'git-graph'/'models'


def initialize_models():
    directory=config_dir()
    directory.mkdir(parents=True,exist_ok=True)
    for name,model in DEFAULTS.items():
        path=directory/(name+'.toml')
        if not path.exists(): path.write_text(model_text(model))
    return directory


def list_models(directory):
    return [p.stem for p in directory.iterdir() if p.suffix=='.toml']


def load_model(name,directory):
    path=directory/(name+'.toml')
    if not path.exists():
        raise ModelError(f"ERROR: No branching model named '{name}' found in {directory}\n       Available models are: "+', '.join(list_models(directory)))
    text=path.read_text()
    try:
        model=read_toml(text)
    except TomlError as e:
        line=text.count('\n',0,e.pos)+1
        col=e.pos-(text.rfind('\n',0,e.pos)+1)+1
        raise ModelError(f'ERROR: {e} at line {line} column {col}')
    for key in ('persistence','order','terminal_colors','svg_colors'):
        if key not in model:
            raise ModelError(f'ERROR: missing field `{key}`')
    return BranchModel(model)

COLORS={name:i for i,name in enumerate(['black','red','green','yellow','blue','magenta','cyan','white'])}
COLORS.update({'bright_'+k:v+8 for k,v in list(COLORS.items())})

class BranchModel:
    def __init__(self,data):
        self.data=data
    def matches_name(self,name):
        return name[7:] if name.startswith('origin/') else name
    def group(self,name,kind):
        name=self.matches_name(name)
        for i,patt in enumerate(self.data[kind]):
            if re.search(patt,name): return i
        return len(self.data[kind])
    def color(self,name,index,svg=False):
        colors=self.data['svg_colors' if svg else 'terminal_colors']
        name=self.matches_name(name)
        choices=colors.get('unknown',['gray' if svg else 'white'])
        for patt,items in colors.get('matches',[]):
            if re.search(patt,name):
                choices=items
                break
        c=choices[index%len(choices)]
        if svg:return c
        if c in COLORS:return COLORS[c]
        try: return int(c) % 256
        except (ValueError,TypeError): raise ModelError(f"Unknown terminal color '{c}'")
PY"}

