"""Commit pretty formats, decorations, dates and text wrapping."""
import datetime
import re
import textwrap
import time

ANSI=re.compile(r'\x1b\[[0-9;]*m')

def paint(text,color,enabled=True):
    return f'\x1b[38;5;{color}m{text}\x1b[0m' if enabled and text else text


def date_text(sig,short=False,relative=False):
    stamp,offset=sig[2:]
    if relative:return relative_date(stamp)
    try:
        tz=datetime.timezone(datetime.timedelta(minutes=offset))
        d=datetime.datetime.fromtimestamp(stamp,tz)
    except (ValueError,OverflowError,OSError):return ''
    if short:return f'{d.year:04}-{d.month:02}-{d.day:02}'
    days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun']
    months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
    sign='-' if offset<0 else '+'
    off=abs(offset)
    return f'{days[d.weekday()]} {months[d.month-1]} {d.day:2} {d.hour:02}:{d.minute:02}:{d.second:02} {d.year:04} {sign}{off//60:02}{off%60:02}'


def relative_date(stamp):
    delta=int(time.time())-stamp
    if delta<0:return 'in the future'
    def plural(n,s):return f'{n} {s}'+('' if n==1 else 's')+' ago'
    if delta<90:return plural(delta,'second')
    mins=(delta+30)//60
    if mins<90:return plural(mins,'minute')
    hours=(mins+30)//60
    if hours<36:return plural(hours,'hour')
    days=(hours+12)//24
    if days<14:return plural(days,'day')
    if days<70:return plural((days+3)//7,'week')
    if days<365:return plural((days+15)//30,'month')
    if days<1825:
