from dataclasses import dataclass, field
from formatting import paint

N,E,S,W=1,2,4,8

@dataclass(eq=False)
class Event:
    child: object
    parent: object
    merge: bool=False
    row: object=None
    @property
    def a(self):return self.child.branch.column
    @property
    def b(self):return self.parent.branch.column
    @property
    def left(self):return min(self.a,self.b)
    @property
    def right(self):return max(self.a,self.b)

@dataclass(eq=False)
class Row:
    commit: object=None
    events: list=field(default_factory=list)
    text: str=''

class TerminalRenderer:
    def __init__(self,graph,formatter,style='normal',sparse=False,reverse=False,color=False):
        self.graph=graph;self.formatter=formatter
        self.style=style;self.sparse=sparse;self.reverse=reverse;self.color=color
        self.nodes=[Row(c) for c in graph.commits]
        self.gaps=[[] for i in range(len(self.nodes)+1)]
        self.events=[]

    def compatible(self,row,event):
        if row.commit:
            col=row.commit.branch.column
            if event.left<=col<=event.right:
                if not(event.merge and row.commit is event.child):return False
        for prev in row.events:
            if event.right<prev.left or event.left>prev.right:continue
            if not event.merge and not prev.merge and event.parent is prev.parent:continue
            return False
        return True

    def put_in_gap(self,event,gap):
        for row in self.gaps[gap]:
            if self.compatible(row,event):break
        else:
            row=Row();self.gaps[gap].append(row)
        row.events.append(event);event.row=row

    def schedule(self):
