            if token=='help':
                sys.stdout.write(f'Print this message or the help of the given subcommand(s)\n\nUsage: {prog} help [COMMAND]...\n\nArguments:\n  [COMMAND]...  Print help for the subcommand(s)\n\nOptions:\n  -h, --help  Print help\n');raise Exit(0)
            cli_error(f"unrecognized subcommand '{token}'",prog)
        if token=='--' and not end_options:
            end_options=True;continue
        if token.startswith('-') and token!='-' and not end_options:
