def repo_model(repo):
    path=repo.gitdir/'git-graph.toml'
    if not path.exists():return None
    try:return read_toml(path.read_text()).get('model')
    except TomlError as e:raise ModelError(f'ERROR: {e}')


def run(argv):
    prog=program_name()
    opts,command,arg=parse(list(argv),prog)
    if command=='model' and opts.get('model_list'):
        directory=initialize_models()
        sys.stdout.write(''.join(s+'\n' for s in list_models(directory)))
        return
    repo=Repository(opts.get('path','.'),opts.get('skip-repo-owner-validation',False))
    directory=initialize_models()
