            else:width=positive(wrapping[0])
            i1=positive(wrapping[1]) if len(wrapping)>1 else 0
            i2=positive(wrapping[2]) if len(wrapping)>2 else 0
        except ValueError:raise ModelError("ERROR: Can't parse option --wrap '"+' '.join(wrapping)+"' to integers.")
        if width=='auto':
            if sys.stdout.isatty():
