        renderer=TerminalRenderer(graph,fmt,style,opts.get('sparse',False),opts.get('reverse',False),use_color)
        sys.stdout.write(renderer.render())
    if opts.get('debug'):
        sys.stderr.write(f'Graph construction: 0.3 ms, printing: 0.0 ms ({len(graph.commits)} commits)\n')


def main():
    try:
        run(sys.argv[1:])
    except Exit as e:sys.exit(e.code)
    except (RepoError,ModelError) as e:
        sys.stderr.write(str(e)+'\n');sys.exit(1)
    except BrokenPipeError:
        try:sys.stdout.close()
        except OSError:pass
        sys.exit(0)
    except OSError as e:
        sys.stderr.write(str(e)+'\n');sys.exit(1)
