def positive(s):
    if not re.fullmatch(r'\+?\d+',s,re.ASCII):raise ValueError()
    n=int(s)
    if n>2**64-1:raise ValueError()
    return n


def repo_model(repo):
    path=repo.gitdir/'git-graph.toml'
    if not path.exists():return None
    try:return read_toml(path.read_text()).get('model')
    except TomlError as e:raise ModelError(f'ERROR: {e}')


def run(argv):
    prog=program_name()
    opts,command,arg=parse(list(argv),prog)
    if command=='model' and opts.get('model_list'):
        directory=initialize_models()
        sys.stdout.write(''.join(s+'\n' for s in list_models(directory)))
        return
    repo=Repository(opts.get('path','.'),opts.get('skip-repo-owner-validation',False))
    directory=initialize_models()
    if command=='model':
        if arg is None:
            name=repo_model(repo)
            sys.stdout.write(name if name is not None else 'No branching model set')
        else:
            load_model(arg,directory)
            import json
            (repo.gitdir/'git-graph.toml').write_text('model = '+json.dumps(arg)+'\n')
            sys.stderr.write(f"Branching model set to '{arg}'")
        return
