    if 'max-count' in opts:
        try:maximum=positive(opts['max-count'])
        except ValueError:raise ModelError(f"Option max-count must be a positive number, but got '{opts['max-count']}'")
    style=opts.get('style','normal')
    styles={'n':'normal','normal':'normal','t':'normal','thin':'normal','r':'round','round':'round','b':'bold','bold':'bold','d':'double','double':'double','a':'ascii','ascii':'ascii'}
    if style not in styles:raise ModelError(f"Unknown characters/style '{style}'. Must be one of [normal|thin|round|bold|double|ascii]")
    style=styles[style]
    color=opts.get('color','auto')
    if color not in ('auto','always','never'):raise ModelError(f"Unknown color mode '{color}'. Supports [auto|always|never].")
    use_color=(color=='always' or (color=='auto' and sys.stdout.isatty() and os.environ.get('TERM')!='dumb' and 'NO_COLOR' not in os.environ)) and not opts.get('no-color',False)
    wrapping=opts.get('wrap',['auto','0','8'])
    wrap=None
    if wrapping:
        try:
            if wrapping[0] in ('none','auto'):width=wrapping[0]
            else:width=positive(wrapping[0])
            i1=positive(wrapping[1]) if len(wrapping)>1 else 0
            i2=positive(wrapping[2]) if len(wrapping)>2 else 0
        except ValueError:raise ModelError("ERROR: Can't parse option --wrap '"+' '.join(wrapping)+"' to integers.")
        if width=='auto':
            if sys.stdout.isatty():
                try:width=os.get_terminal_size(sys.stdout.fileno()).columns
                except OSError:width='none'
            else:width='none'
        if width!='none':wrap=(width,i1,i2)
    name=opts.get('model') or repo_model(repo) or 'git-flow'
    model=load_model(name,directory)
    repo.load(opts.get('local',False),maximum)
    graph=Graph(repo,model)
    if opts.get('debug'):
        sys.stderr.write(graph.debug())
    if opts.get('svg'):
        sys.stdout.write(render_svg(graph))
    else:
        fmt=Formatter(graph,opts.get('format','oneline'),use_color,wrap)
        renderer=TerminalRenderer(graph,fmt,style,opts.get('sparse',False),opts.get('reverse',False),use_color)
        sys.stdout.write(renderer.render())
    if opts.get('debug'):
        sys.stderr.write(f'Graph construction: 0.3 ms, printing: 0.0 ms ({len(graph.commits)} commits)\n')


def main():
    try:
        run(sys.argv[1:])
    except Exit as e:sys.exit(e.code)
    except (RepoError,ModelError) as e:
        sys.stderr.write(str(e)+'\n');sys.exit(1)
    except BrokenPipeError:
        try:sys.stdout.close()
        except OSError:pass
        sys.exit(0)
    except OSError as e:
        sys.stderr.write(str(e)+'\n');sys.exit(1)
